/**
 * 多卷轴slots 参考queenSea_Slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        MaxSlotsCnt:4,      // 最大slots个数
        _slotsCnt:1,        // 当前显示得slots个数
        _unitSlotColCnt:5, // 一个slot单位列数
        _nowJpLockWeight:0, 
        _nowJpUnlockWeight:0,
    },
    
    //初始化
    Init:function(){
        this._super();
        this.changeSlots();
     },


    //重写
    StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this.getCurReels());  //Changed ...

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime();
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            Global.SlotsSoundMgr.playNormalBgm()
        }
        
        SlotsFacade.extraWildCmp.hideWild();
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        SlotsFacade.flowCtrl.onMsgSpine(msg);
    },
 
    /**
     * 根据服务端序号获取本地的symbol
     * @override
     * @param {*} idx 
     */
    GetSymbolByIdx:function(idx){
        let selfCol = this._unitSlotColCnt*this._slotsCnt;
        let col = (idx - 1) % selfCol
        let row = this._row - Math.floor((idx -1)/selfCol) -1
        return this._reels[col].GetSymbolByRow(row)
    },

    /**
     * @override
     * @param {*} msg 
     */
    SetSlotsResult:function(msg){
        let cardsList = msg.resultCards;
        //整理cards
        if (msg.mapFreeGameData && msg.mapFreeGameData.length > 0) {
            cardsList = [];
            for (let i=0; i<this._row; i++) {
                for (let slotResult of msg.mapFreeGameData) {
                    for (let j=0; j<this._unitSlotColCnt; j++) {
                        cardsList.push(slotResult.cards[i*this._unitSlotColCnt+j]);
                    }
                }
            }
        }

        let reelResults = []
        let aCol = this.getCurrReelCnt();
        let bonusCoinIdxs = SlotsFacade.dm.getSpinData().bonusCoinIdxs || [];
        bonusCoinIdxs = bonusCoinIdxs.concat();
        let bonusCoins = SlotsFacade.dm.getSpinData().bonusCoins || [];
        bonusCoins = bonusCoins.concat();
        for(let i = 0;i < cardsList.length; i++){
            let row = Math.floor(i / aCol)
            let col = i % aCol
            //配置中有没有这个元素
            if(this._cfg.symbol[cardsList[i]]){
                let res = {};
                res.sid = cardsList[i];
                if(bonusCoinIdxs.length && bonusCoinIdxs[0] == i+1) {
                    res.data = bonusCoins[0];
                    bonusCoinIdxs.shift();
                    bonusCoins.shift();
                }
                if(!reelResults[col]) {
                    reelResults[col] = [];
                }
                reelResults[col].unshift(res)
            }
        }
        for(let j = 0; j < 5*this._slotsCnt; j++){
            let item = this._reels[j]
            let reelRes = reelResults[j]
            item.SetResult(reelRes)
        }
    },

    SetReelStateInfo:function(cards){
        // 免费不进行加速检测
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._unitSlotColCnt;
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info); 
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);  
            let haveCount = 0
    
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);  
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    /**
     * 检测列是否有scatter图标
     */
    hasScatter(colIdx) {
        let scatterId = cc.vv.gameData.getGameCfg().scatterId;
        let sysResult = this._reels[colIdx]._symbols;
        for(let j = 0; j < 3; j++){
            if(sysResult[j].GetShowId() == scatterId){
                return true;
            }
        }
        return false;
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 播放scatter 中奖动画
     */
    async playScatter(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.setAnimationToTop(false);
            item.playTriggerAnimation()
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },

    /**
     * 返回当前有效得reels
     */
    getCurReels () {
        return this._reels.slice(0, this.getCurrReelCnt());
    },

    /**
     * 返回当前有效reels个数
     */
    getCurrReelCnt() {
        return this._slotsCnt * this._unitSlotColCnt;
    },

    /**
     * 显示slots
     */
    showSlots () {
        //显示背景
        for (let i=1; i<= this.MaxSlotsCnt; i++)  {
            cc.find("reels_bg" + i, this.node).active = i <= this._slotsCnt;
        }
        //显示reels
        let cnt = this.getCurrReelCnt();
        for(let i=0; i<this._col; i++) {
            this._reels[i].node.active = i < cnt;
        }

        if(this._slotsCnt <= 2){
            this.node.scale = 1;
        } else if(this._slotsCnt == 3){
            this.node.scale = 0.8;
        } else if(this._slotsCnt == 4){
            this.node.scale = 0.65;
        }
    },

    /**
     * 显示列wild遮罩
     */
    showSlotsWildMask() {
        if(this._slotsCnt > 1) {
            let wildCols = SlotsFacade.dm.getGameCfg().mapCfg[SlotsFacade.dm.energyData.map_idx+""].slot.wilds;
            for(let i=0; i<this._reels.length; i++) {
                let col = i%5 + 1; // 列数1开始
                this._reels[i].showWildMask(wildCols.includes(col));
            }
        }else {
            for(let i=0; i<this._unitSlotColCnt; i++) {
                this._reels[i].showWildMask(false);
            }
        }
    },

    changeSlots() {
        this._slotsCnt = SlotsFacade.dm.getSlotsCnt();
        SlotsFacade.mainPanel.logo_spine.active = this._slotsCnt != 4 && this._slotsCnt != 1;
        this.showSlotsWildMask();
        this.showSlots();
    },

    /**
     * @override
     */
    ShowWinTrace:function(){
        let allWinIdx = []
        let freeGameSlots = SlotsFacade.dm.getSpinData().mapFreeGameData;
        if (freeGameSlots && freeGameSlots.length > 0) {
            for (let n in freeGameSlots) {
                let zjLuxian = freeGameSlots[n].traceResult;
                for(let i = 0; i < zjLuxian.length; i++){
                    let item = zjLuxian[i]
                    for(let idx = 0; idx < item.indexs.length; idx++){
                        let posIdx = item.indexs[idx];
                        let row = Math.floor((posIdx - 1)/5);
                        let col = (posIdx - 1)%5;
                        allWinIdx[row*5*this._slotsCnt + n*5 + col + 1] = 1;
                    }
                }
            }
        } else {
            let spinData = SlotsFacade.dm.getSpinData();
            for(let i = 0; i < spinData.zjLuXian.length; i++){
                let item = spinData.zjLuXian[i]
                for(let idx = 0; idx < item.indexs.length; idx++){
                    allWinIdx[item.indexs[idx]] = 1;
                }
            }
        }

        // 标记wild 合并情况
        let reels = this.getCurReels();
        let reelsLen = reels.length;
        for(let i=0; i<reelsLen; i++) {
            let r = reels[i];
            let flags  = [false, false, false];
            for(let j=0; j<3; j++) {
                let s = r._symbols[j];
                let idx = (2-j)*reelsLen + (i+1);
                if(s.GetShowId() == 1 && allWinIdx[idx]) {
                    flags[j] = true;
                }
            }
            if(flags[0] && flags[1] && flags[2]) {
                r._symbols[0].wildAniCount = 3;
                r._symbols[1].wildAniCount = 0;
                r._symbols[2].wildAniCount = 0;
            }else if(flags[0] && flags[1]) {
                r._symbols[0].wildAniCount = 2;
                r._symbols[1].wildAniCount = 0;
            }else if(flags[1] && flags[2]) {
                r._symbols[1].wildAniCount = 2;
                r._symbols[2].wildAniCount = 0;
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    clearFreeSymbols() {
        for(let i=5; i<this._reels.length; i++) {
            let symbols = this._reels[i]._symbols;
            for(let j=0; j<symbols.length; j++) {
                symbols[j].StartMove();
            }
        }
    },

    /**
     * 通过服务器idx获取全局坐标 0~15内的idx
     * @param {*} idx 
     */
    getIdxGlobalPos(idx) {
        let col = (idx - 1) % 5;
        let row = this._row - Math.floor((idx -1)/5) -1
        let reel = this._reels[col];
        let pos = reel.GetSymbolPosByRow(row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },
});
