/**
 * @class Magician_ExtraWildGame
 */
cc.Class({
    extends: cc.Component,

    properties: {
        effect_pos1:cc.Node,
        effect_pos2:cc.Node,
        apear_full:sp.Skeleton,
        apear1:cc.Node,
        apear2:cc.Node,
        apear_col: [sp.Skeleton],
        liuguanlizi:cc.Node,
        itemsMaskNode:cc.Node,
        extra_wild_pre_ani:cc.Node,
        extra_wild_area_ani:cc.Node,
        wilds_node:cc.Node,
        float_wild_item:cc.Node,
        _wildsArr:null,
    },

    onLoad() {
    },

    start() {
        this.scheduleOnce(()=>{
            this.initFloatWilds();
        });
    },

    initFloatWilds() {
        this._wildsArr = [];
        for(let i=0; i<15; i++) {
            let item = cc.instantiate(this.float_wild_item);
            item.parent = this.wilds_node;
            let pos = SlotsFacade.slots.getIdxGlobalPos(i+1);
            pos = this.wilds_node.convertToNodeSpaceAR(pos);
            item.x = pos.x;
            item.y = pos.y;
            this._wildsArr.push(item);
        }
    },

    /**
     * 开始 ExtraWild随机游戏流程
     */
    async startExtraWildFlow() {
        await this._showPreAni();
        await this._showGenWild();
        await this._exitExtraWild();    
    },

    async _exitExtraWild() {
        this.itemsMaskNode.runAction(cc.fadeOut(1));
        await SlotsFacade.delayTime(0.6);
        this.extra_wild_area_ani.runAction(cc.fadeOut(0.2));
        await SlotsFacade.delayTime(0.3);
    },

    /**
     * 拆分wild论次 
     * type = 1 一次播完
     * type = 2 一列
     * type = 3 人物角色播放
     */
    _getRoundsArr() {
        let wildIndexs = SlotsFacade.dm.getExtraWildIndexs().concat();
        let maxCount = 3; // 最大拆分次数
        
        if(wildIndexs.length > 5 && Math.random()> 0.6) {
            return [{type:1, indexs:wildIndexs}];
        }

        let roundsArr = [];   // 二维数组，保存拆分后的数组

        // 拆分成列 动画
        let cols = [[], [], [], [], []];        
        for(let i=0; i<wildIndexs.length; i++) {
            cols[(wildIndexs[i]-1)%5].push(wildIndexs[i]);
        }
        for(let i=0; i<cols.length; i++) {
            if(cols[i].length == 3) {
                roundsArr.push({type:2, indexs:cols[i]});
                for(let j=0; j<cols[i].length; j++) {
                    let index = wildIndexs.indexOf(cols[i][j]);
                    if(index != -1) {
                        wildIndexs.splice(index, 1);
                    }
                }
            }
        }
        
        // 拆分成角色动画
        while(maxCount > 0 && wildIndexs.length > 0) {
            if(maxCount == 1) { // 如果只剩下一次拆分
                roundsArr.push({type:3, indexs:wildIndexs.concat()});
                wildIndexs = []; 
            }else {
                let count = Math.ceil(wildIndexs.length * Math.random());
                let indexs = [];
                for(let i=0; i<count; i++) {
                    indexs.push(wildIndexs.pop());
                }
                roundsArr.push({type:3, indexs:indexs});
            }

            if(wildIndexs.length < 1) {
                break;
            }
            maxCount--;
        }
        return roundsArr;
    },

    /**
     * 显示生成wild动画
     */
    async _showGenWild() {
        let roundsArr = this._getRoundsArr();
        for(let i=0; i<roundsArr.length; i++) {
            let round = roundsArr[i];
            switch(round.type) {
                case 1:
                    await this._playAppearFullRound(round.indexs);
                    break;
                case 2:
                    await this._playColRound(round.indexs);
                    break;
                case 3:
                    await this._playARound(round.indexs);
                    break;
            }
        }
    },

    /**
     * 一次性产生所有wild
     */
    async _playAppearFullRound(indexs) {
        SlotsFacade.soundMgr.playEffect("act1");
        this.apear_full.node.active = true;
        this.apear_full.setAnimation(0, "animation", false);
        this.apear_full.setCompleteListener(()=>{
            this.apear_full.setCompleteListener(null);
            this.apear_full.node.active = false;
        });
        let t1 = 2.5;
        let t2 = 5;
        await SlotsFacade.delayTime(t1);
        for(let i=0; i<indexs.length; i++) {
            let item = this._wildsArr[indexs[i]-1];
            let apearAni = cc.instantiate(this.apear2);
            apearAni.x = item.x;
            apearAni.y = item.y;
            apearAni.parent = this.wilds_node;
            apearAni.active = true;
            let apearSpin = apearAni.getComponent(sp.Skeleton);
            apearSpin.setAnimation(0, "animation", false);
            apearSpin.setCompleteListener(()=>{
                apearSpin.setCompleteListener(null);
                apearAni.removeFromParent();
                item.active = true;
            });
        }
        await SlotsFacade.delayTime(t2);
    },

    /**
     * 播放一轮
     * @param {*} indexs 
     */
    async _playColRound(indexs) {
        SlotsFacade.soundMgr.playEffect("act3");
        let colIndex = (indexs[0]-1) % 5;
        let colSpine = this.apear_col[colIndex];
        colSpine.node.active = true;
        colSpine.setAnimation(0, "animation", false);
        colSpine.setCompleteListener(()=>{
            colSpine.setCompleteListener(null);
            colSpine.node.active = false;
        });
        let t1 = 1.7;
        let t2 = 0.15;
        for(let i=0; i<indexs.length; i++) {
            this.scheduleOnce(()=>{
                let item = this._wildsArr[indexs[i]-1];
                let apearAni = cc.instantiate(this.apear2);
                apearAni.x = item.x;
                apearAni.y = item.y;
                apearAni.parent = this.wilds_node;
                apearAni.active = true;
                let apearSpin = apearAni.getComponent(sp.Skeleton);
                apearSpin.setAnimation(0, "animation", false);
                apearSpin.setCompleteListener(()=>{
                    apearSpin.setCompleteListener(null);
                    apearAni.removeFromParent();
                    item.active = true;
                });
            }, t1 + i*t2);
        }
        await SlotsFacade.delayTime(2.8);
    },

    /**
     * 播放一轮角色wild动画
     * @param {number} indexs 
     */
    async _playARound(indexs) {
        let data = SlotsFacade.character.play(indexs.length);
        await SlotsFacade.delayTime(data.triggerTime);
        let startPos = null;
        if(data.roleName == "pos1") {
            startPos = this.effect_pos1.getPosition();
            SlotsFacade.soundMgr.playEffect("act6");
        }else {
            startPos = this.effect_pos2.getPosition();
            SlotsFacade.soundMgr.playEffect("act7");
        }
        await this._playTrackAni(indexs, startPos);
    },

    /**
     * 粒子飞行动画
     * @param {number} indexs 
     * @param {cc.Vec2} startPos 
     */
    _playTrackAni(indexs, startPos) {
        let promissArr = [];
        for(let i=0; i<indexs.length; i++) {
            // 生成粒子
            let lz = cc.instantiate(this.liuguanlizi);
            lz.parent = this.node;
            lz.x = startPos.x;
            lz.y = startPos.y;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();
            lz.active = true;

            // 移动粒子
            let item = this._wildsArr[indexs[i]-1];
            let iPos = item.convertToWorldSpaceAR(cc.v2(0, 0));
            iPos = this.node.convertToNodeSpaceAR(iPos);

            promissArr.push(this._moveAParticle(lz, iPos, item));
        }
        return Promise.all(promissArr);
    },

    /**
     * 移动一个粒子
     * @param par
     * @param endPos
     * @returns {Promise<unknown>}
     * @private
     */
    _moveAParticle(par, endPos, item) {
        return new Promise((res) => {
            cc.tween(par)
                .to(0.5, {x:endPos.x, y:endPos.y})
                .call(()=> {
                    par.removeFromParent();
                    res();
                })
                .start();
        }).then(() => {
            return new Promise((res)=> {
                let apearAni = cc.instantiate(this.apear1);
                apearAni.x = endPos.x;
                apearAni.y = endPos.y;
                apearAni.parent = this.node;
                apearAni.active = true;
                let apearSpin = apearAni.getComponent(sp.Skeleton);
                apearSpin.setAnimation(0, "animation", false);
                apearSpin.setCompleteListener(()=>{
                    apearSpin.setCompleteListener(null);
                    apearAni.removeFromParent();
                    item.active = true;
                    res();
                });
            })
        });
    },

    /**
     * 显示进入extra wild 的过度动画
     */
    _showPreAni() {
        return new Promise((res, rej)=> {
            this.extra_wild_pre_ani.active = true;
            // wild pre ani 动画
            let preAni = this.extra_wild_pre_ani.getComponent(sp.Skeleton);
            preAni.setCompleteListener(()=>{
                preAni.setCompleteListener(null);
                res();
            });
            preAni.setAnimation(0, 'animation', false);

            // 显示mask背景
            this.itemsMaskNode.active = true;
            this.itemsMaskNode.opacity= 0;
            cc.tween(this.itemsMaskNode)
                .to(1, {opacity:150})
                .start();

            // 显示ExtraWild背景框动画
            this.scheduleOnce(()=>{
                this.extra_wild_area_ani.active = true;
                this.extra_wild_area_ani.opacity = 0;
                this.extra_wild_area_ani.runAction(cc.fadeIn(0.2));
            }, 0.7);
            SlotsFacade.soundMgr.playEffect("act2");
        });
    },

    hideWild() {
        this._wildsArr.forEach(element => {
            element.active = false;
        });
    }
});
