/**
 * 弹窗管理器
 * @class Magician_Popup
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {

    },

    /**
     * 弹窗通用逻辑
     * @param {*} param 
     * popupName       -- 弹框节点名
     * startAniName    -- 弹框打开 spine动画名称
     * idelAniName     -- 弹框打开后 spine动画名称
     * endAniName      -- 关闭弹窗 spine动画名称
     * labelValue      -- 数字文本值
     * labelNeedRoll   -- 文本是否需要滚动
     * @param {Function} cb 
     */
    async _showPopup(param, cb) {
        this.bg.active = true;
        let panel = this.node.getChildByName(param.popupName);
        panel.active = true;
        // 弹窗出现
        let spine = null;
        if(param.startAniName) {
            spine = panel.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.active = true;
            spine.setAnimation(0, param.startAniName, false);
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                spine.setAnimation(0, param.idelAniName, true);
            });
        }
        // 显示文本
        let rollLabel = panel.getChildByName("label_win").getComponent("LabelRollCmp");
        rollLabel.node.active = true;
        rollLabel.node.scale = 0;
        cc.tween(rollLabel.node)
            .delay(0.1)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        if(param.labelNeedRoll) {
            rollLabel.startRoll(0, param.labelValue)
        }else {
            rollLabel.value = param.labelValue;
        }
        // 显示按钮
        let btn_ok = panel.getChildByName("btn_ok")
        btn_ok.scale = 0;
        btn_ok.active = true;
        btn_ok.getComponent(cc.Button).interactable = true;
        cc.tween(btn_ok)
            .delay(0.1)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();
        await cc.vv.gameData.awaitTime(0.6);
        // 按钮点击
        let handler = () => {
            Global.SlotsSoundMgr.playEffect("common_click");
            btn_ok.stopAllActions();
            btn_ok.getComponent(cc.Button).interactable = false;
            btn_ok.off(cc.Node.EventType.TOUCH_END, handler);
            // 背景
            this.bg.active = false;
            let promisesArr = [];
            promisesArr.push(new Promise(res=>{
                // spine关闭动画
                spine.setAnimation(0, param.endAniName, false)
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    res();
                })
            }));
            promisesArr.push(new Promise(res=>{
                // 按钮
                cc.tween(btn_ok)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    btn_ok.active = false;
                    res();
                })
                .start();
            }));
            promisesArr.push(new Promise(res=>{
                // 文本
                cc.tween(rollLabel.node)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    rollLabel.node.active = false;
                    res();
                })
                .start();
            }));
            Promise.all(promisesArr).then((results)=>{
                panel.active = false;
                if(cb) {
                    cb()
                }
            });
            
        }
        cc.vv.gameData.checkAutoPlay(btn_ok, handler);
        btn_ok.on(cc.Node.EventType.TOUCH_END, handler);
    },

    /**
     * 显示赢取金币奖励
     * @param {number} goldNumb
     * @param {number} goldType 
     * 1：地图转盘赢取奖励
     * 2：scatter转盘赢取奖励
     * 3：免费游戏之后赢取金币奖励
     */
    async showWinGold(goldNumb, goldType) {
        let param = {
            popupName:"win_gold_dialog",
            startAniName:"animation1",
            idelAniName:"animation1_1",
            endAniName:"animation1_2",
            labelValue:goldNumb,
            labelNeedRoll:true
        }
        switch (goldType) {
            case 1:
                param = {
                    popupName:"win_gold_dialog_type1",
                    startAniName:"animation1",
                    idelAniName:"animation2",
                    endAniName:"animation3",
                    labelValue:goldNumb,
                    labelNeedRoll:true
                }
                break;
            case 2:
                param = {
                    popupName:"win_gold_dialog_type2",
                    startAniName:"animation1",
                    idelAniName:"animation1_1",
                    endAniName:"animation1_2",
                    labelValue:goldNumb,
                    labelNeedRoll:true
                }
                break;
            default:
                param = {
                    popupName:"win_gold_dialog_type3",
                    startAniName:"animation1",
                    idelAniName:"animation1_1",
                    endAniName:"animation1_2",
                    labelValue:goldNumb,
                    labelNeedRoll:true
                }
                break;
        }
        await new Promise((res, rej)=> {
            this._showPopup(param, res)
        });
    },

    /**
     * 显示赢取jackport金币奖励
     * @param {number} goldNumb 
    */
   async showWinJackportGold(goldNumb) {
        let param = {
            popupName:"win_gold_dialog_type3",
            startAniName:"animation1_1",
            idelAniName:"animation1_3",
            endAniName:"animation1_4",
            labelValue:goldNumb,
            labelNeedRoll:true
        }
        await new Promise((res, rej)=> {
            this._showPopup(param, res)
        });
    },

    /**
     * 显示赢取免费次数
     * @param {number} cnt 
    */
    async showWinFreeCnt(cnt) {
        let param = {
            popupName : "win_free_cnt_dialog",
            startAniName : "animation2",
            idelAniName : "animation2_1",
            endAniName : "animation2_2",
            labelValue : cnt,
            labelNeedRoll : false
        };
        await new Promise((res, rej)=> {
            this._showPopup(param, res)
        });
    }
 })