/**
 * @class Magician_MapWheel
 */
cc.Class({
    extends: cc.Component,

    properties: {
        machine:{
            default:null,
            visible:false
        },
        roundCount: 10,     // 圈数
        _canSpin:false,     // 是否可转
        _wheel_type:0,      // 转盘类型 0普通 1高级
        _callBack:null,     // 完成后回调
        _data:null,         // 请求数据结果

        wheel:cc.Node,
        bg: cc.Node,
        board:cc.Node,
        btn_spin:cc.Node,
        spine_btn_spin:sp.Skeleton,
        spine_fire:sp.Skeleton,
        spine_win:sp.Skeleton,
        spine_wheel_bg:sp.Skeleton,
        label_start_prize:cc.Label,
    },

    _getRotation(index) {
        let ret = -this.roundCount * 360;
        let unitAngle = 360/6;
        let indexsAngle = [
            0,
            -360+unitAngle*1,
            -360+unitAngle*2,
            -360+unitAngle*3,
            -360+unitAngle*4,
            -360+unitAngle*5
        ];
        ret += indexsAngle[index];
        return ret;
    },

    onLoad() {
        this._initListener();
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this._onSubGameData, false, this);
    },

    _initListener() {
        this.btn_spin.on(cc.Node.EventType.TOUCH_END, this._onStartWheelHandler, this);
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this._onSubGameData, this);
    },

    _onSubGameData(msg) {
        // let msg =  {"data":{"coinpool":50000,"rtype":1,"idx":1,"extraFreeCnt":1},"uid":104711,"c":51,"code":200};
        if(msg && msg.data && msg.data.rtype == 1) {
            this._data = msg.data;
            this._startWheel();
        }
    },

    _onStartWheelHandler() {
        if(!this._canSpin) {
            return;
        }
        this.btn_spin.stopAllActions();
        this._canSpin = false;
        SlotsFacade.soundMgr.playEffect("spin");
        SlotsFacade.dm.reqSubGame(1)
    },

    _reset() {
        this.board.angle = 0;
        this.bg.active = false;
        this.wheel.active = false;
        this.wheel.y = this.wheel.height/2;
        this.spine_btn_spin.node.active = false;
        this.spine_wheel_bg.node.active = false;
        this.spine_win.node.active = false;
        this.spine_fire.active = false;
        this.label_start_prize.string = "";
    },

    async _startWheel() {
        this.spine_btn_spin.node.active = false;
        this.btn_spin.getComponent("ImgSwitchCmp").setIndex(this._wheel_type + 2);

        this.spine_fire.node.active = true;
        this.spine_wheel_bg.node.active = true;
        SlotsFacade.soundMgr.playEffect("wheel_roll");
        await new Promise((res)=> {
            cc.tween(this.board)
                .to(4, {angle:this._getRotation(this._data.idx-1)}, { easing: 'quartInOut' })
                .call(()=> {
                    if(this._data.coin) {
                       SlotsFacade.soundMgr.playEffect("map_button");
                    }else {
                       SlotsFacade.soundMgr.playEffect("pass1");
                    }
                    res();
                })
                .start();
        });

        this.spine_fire.node.active = false;
        this.spine_wheel_bg.node.active = false;
        this.spine_win.node.active = true;
        this.spine_win.setAnimation(0, "animation" + (this._wheel_type+1), true);
        await SlotsFacade.delayTime(2);
        this._completeWheel();
    },

    /**
     * 旋转完毕
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _completeWheel() {
        if(this._data.coin) {
            SlotsFacade.soundMgr.playEffect("jp_collect_popup");
            await SlotsFacade.popup.showWinGold(this._data.coin, 1);
        }
        await this.close();
        if(this._callBack) {
            this._callBack(this._data);
        }
    },

    _freshView() {
        this.btn_spin.getComponent("ImgSwitchCmp").setIndex(this._wheel_type)
        this.wheel.getChildByName("bar_left").getComponent("ImgSwitchCmp").setIndex(this._wheel_type);
        this.wheel.getChildByName("bar_right").getComponent("ImgSwitchCmp").setIndex(this._wheel_type);
        this.board.getComponent("ImgSwitchCmp").setIndex(this._wheel_type);
        this.wheel.getChildByName("arrow").getComponent("ImgSwitchCmp").setIndex(this._wheel_type);
    },

    /**
     * 开始 开始转盘流程
     */
    open(cb, data) {
        this._callBack = cb;
        this.node.active = true;
        this._reset();
        this._wheel_type = data.wheel_type;
        this._canSpin = true;
        this._freshView();
        let startPrice = data.startPrice;
        if(!data.startPrice) {
            startPrice = 0;
        }
        this.label_start_prize.string = Global.FormatNumToComma(Math.floor(startPrice));

        // 显示背景
        this.bg.active = true;
        this.bg.opacity = 1;
        this.bg.runAction(cc.fadeTo(1, 200));

        // 显示盘
        this.wheel.active = true;
        cc.tween(this.wheel)
            .to(0.5, {y:0}, {easing:"backOut"})
            .start();

        this.spine_btn_spin.node.active = true;
        this.spine_btn_spin.setAnimation(0, "animation", true);
        this.btn_spin.getComponent("ImgSwitchCmp").setIndex(this._wheel_type);
        cc.vv.gameData.checkAutoPlay(this.btn_spin, this._onStartWheelHandler.bind(this));
    },

    async close() {
        return new Promise((res) => {
            // 隐藏背景
            cc.tween(this.bg)
                .to(0.5, {opacity:0})
                .call(()=>{
                    this.bg.active = false;
                })
                .start();

            // 隐藏转盘
            cc.tween(this.wheel)
                .to(0.5, {y:this.wheel.height/2}, {easing:"backIn"})
                .call(()=>{
                    this.wheel.active = false;
                    this.node.active = false;
                    res();
                })
                .start();
        });
    },
});
