/**
 * @class Magician_GameData
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        resultCards : [],   // 旋转结果数据
        extraWildIndexs:[], // extraWild下标
        energyData  : null,   // 能量数据
        mapFreeGameData: null,
    },

    init(data, gameId) {
        this._super(data, gameId);
        this.energyData = this._deskInfo.colection;
        this.freeTurnTable = this._deskInfo.freeTurnTable;
    },

    OnRcvNetSpine(msg) {
        if(msg.code == 200){
            this.energyData = msg.mapInfo;
            this.bonusData = msg.epicInfo;
            if(msg.randomData && msg.randomData.wild_idxs) {
                this.extraWildIndexs = msg.randomData.wild_idxs;
            }else {
                this.extraWildIndexs = null;
            }
            if(msg.energyData) {
                this.energyData = msg.energyData;
            }
            this.freeTurnTable = msg.freeTurnTable;
            this.mapFreeGameData = msg.mapFreeGameData;
        }
        this._super(msg);
    },

    getSpinData() {
        return this._gameInfo;
    },

    /**
     * 是否有extraWild
     * @returns {boolean}
     */
    hasExtraWild() {
        return this.extraWildIndexs && this.extraWildIndexs.length > 0;
    },

    /**
     * 获取结果中wild的下标
     */
    getResultWildsIndex() {
        let cards = this.getSpinData().resultCards;
        if(!cards || cards.length < 1) {
            return [];
        }
        let ret = [];
        cards.forEach((v, i)=>{
            if(v == 1) {
                ret.push(i+1);
            }
        });
        return ret;
    },

    /**
     * 触发免费游戏 获取scatter 下标
     */
    getScatterIndexs() {
        let ret = [];
        let cards = this.getSpinData().resultCards;
        if(!cards || cards.length < 1) {
            return ret;
        }
        for(let i=0; i<cards.length; i++) {
            if(cards[i] == 2) {
                ret.push(i + 1);
            }
        }
        return ret;
    },

    /**
     * 请求子游戏数据51
     * @param gameType
     */
    reqSubGame(gameType) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:{rtype:gameType}
        };
        cc.vv.NetManager.send(req, true);
    },
    ///////////////////////////收集相关/////////////////
    /**
     * 当前下注是否达到收集的条件
     */
    canCollect() {
        return this.GetBetIdx() >= this.energyData.needBet;
    },

    /**
     * 获取当前收集进度
     */
    getCollectPercent() {
        let percent = 0;
        let data = this.energyData;
        if(data) {
            percent = data.currValue / data.fullValue;
            percent = Math.max(0, percent);
            percent = Math.min(1, percent);
        }
        return percent;
    },
    
    ///////////////////////////免费相关///////////////////////////
    /**  
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 获取免费游戏中赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },

    /**
     * 添加免费次数
     */
    addFreeCnt(cnt) {
        this._deskInfo.restFreeCount += cnt;
        this._deskInfo.allFreeCount += cnt;
    },

    ///////////////////////////多卷轴相关///////////////////////////////
    /**
     * 是否有多转轴 游戏
     */
    hasMultipleSlot() {
        return this.mapFreeGameData && this.mapFreeGameData.length > 0;
    },

    /**
     * 是否第一次触发多转轴游戏
     */
    isFirstTriggerMultipleSlot() {
        return this.hasMultipleSlot() && this.isFistTriggerFree();
    },

    /**
     *  是否结束多卷轴游戏
     */
    isEndMultipleSlot() {
        return this.hasMultipleSlot() && !this.hasFree();
    },

    getExtraWildIndexs() {
        if(this.hasExtraWild()) {
            return this.extraWildIndexs;
        }
        return [];
    },

    /**
     * 获取slots个数
     */
    getSlotsCnt() {
        if(this.energyData.openGame == 2) {
            return this.getGameCfg().mapCfg[this.energyData.map_idx.toString()].slot.cnt;
        }else {
            return 1;
        }
    },
});
