cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        wildMask:cc.Node
    },

    onLoad () {
        this._super();
        this.wildMask = this.node.getChildByName("wild_mask");
    },

    showWildMask(boo) {
        if(this.wildMask) {
            this.wildMask.active = boo;
        }
    }
})
