/**
 * 收集游戏
 * @class Magician_Map
 */
let CollectGameMap = cc.Class({
    extends: cc.Component,

    properties: {
        machine:{
            default:null,
            visible:false
        },

        callBack:null,

        _mapWheel:null,

        map_game_node:null,
        bg:null,
        btn_close:null,
        scrollView:null,
        map_flag:null,
    },

    onLoad() {
        this._bindView();
        this._initListener();
        this._reset();
    },

    _bindView() {
        this.map_game_node = this.node;
        this._mapWheel = this.map_game_node.getChildByName("map_wheel_node").getComponent("Magician_MapWheel");

        this.bg = this.map_game_node.getChildByName("bg");
        this.btn_close = this.map_game_node.getChildByName("btn_close").getComponent(cc.Button);
        this.scrollView = this.map_game_node.getChildByName("scrollview").getComponent(cc.ScrollView);
        this.map_flag = this.scrollView.content.getChildByName("map_flag");
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        for(let i=1; i<=100; i++) {
            let item = this.scrollView.content.getChildByName(i.toString());
            item["id"] = i;
            let icon = item.getChildByName("icon");
            let vo = mapCfg[i.toString()];
            if(vo.type != 3) {
                icon.getComponent("ImgSwitchCmp").setIndex(vo.type - 1);
            }
            item.getChildByName("label_step").getComponent(cc.Label).string = i.toString();
        }
    },

    _initListener() {
        this.btn_close.node.on("click", this._onBtnCloseHandler.bind(this), this);
    },

    async _onBtnCloseHandler() {
        SlotsFacade.soundMgr.playEffect("map_button");
        this.btn_close.interactable = false;
        cc.tween(this.btn_close.node)
            .to(0.3, {scale:0}, {easing:"backIn"})
            .call(()=>{
                this.exitMap();
            })
            .start();
    },

    /**
     * 退出
     */
    exitMap(data) {
        let svNode = this.scrollView.node;
        cc.tween(svNode)
            .to(0.3, {y:svNode.height}, {easing:"cubicOut"})
            .call(()=>{
                this._reset();
                if(this.callBack) {
                    this.callBack(data);
                    this.callBack = null;
                }
            })
            .start();
    },

    /**
     * 进入
     * @param isView 是否是查看
     * @param cb
     * @returns {Promise<void>}
     */
    async enterMap(isView, cb) {
        this.callBack = cb;
        this.map_game_node.active = true;
        await new Promise(res=>{
            this.bg.active = true;
            this.bg.opacity = 0;
            cc.tween(this.bg)
                .to(0.5, {opacity:100})
                .call(()=>{
                    res();
                })
                .start();
        });
        let data = SlotsFacade.dm.energyData;
        let currIndex = data.map_idx;
        if(!isView && data.openGame>0) {
            currIndex -= 1;
        }
        this._freshMap(currIndex);

        if(currIndex > 0) {
            let item = this.scrollView.content.getChildByName(currIndex.toString());
            this.scrollView.scrollToOffset(cc.v2(0, Math.abs(item.y) - this.scrollView.node.height*2/3));
        }else {
            this.scrollView.scrollToBottom();
        }
        await this._scrollViewShow();
        if (isView) {
            this._showCloseBtn();
        }else {
            await this._moveMapFlag(data.map_idx);
            let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
            let vo = mapCfg[data.map_idx.toString()];
            if(vo.type != 3) {
                let respData = await new Promise((res)=> {
                    this._mapWheel.open((ret)=>{res(ret)}, {wheel_type:vo.type-1, startPrice:SlotsFacade.dm.energyData.startPrize});
                });
                if(respData.extraFreeCnt) {
                    await this._addHouseFreeCnt(data.map_idx);
                }
                this.exitMap();
            }else {
                this.exitMap({freeCnt:(5 + (data.extraFreeCnt || 0))});
            }
        }
    },

    /**
     * 加房子的免费次数
     * @returns {Promise<unknown>}
     * @private
     */
    async _addHouseFreeCnt(currIndex) {
        return new Promise(res=>{
            let item = this._findNextHouse(currIndex);
            if(item) {
                let data = SlotsFacade.dm.energyData;
                let extraFreeCnt = data.extraFreeCnt+1 || 0;
                SlotsFacade.dm.energyData.extraFreeCnt = extraFreeCnt;
                item.getChildByName("label_free_count").getComponent("ImgSwitchCmp").setIndex(extraFreeCnt);
                let spine = item.getChildByName("spine_free_count_change").getComponent(sp.Skeleton);
                spine.setAnimation(0, "animation", false);
                spine.setCompleteListener(()=>{
                    spine.setCompleteListener(null);
                    res();
                })
            }else {
                res();
            }
        });
    },

    /**
     * 查找下一个house节点
     * @param currIndex
     * @returns {cc.Node|null}
     * @private
     */
    _findNextHouse(currIndex) {
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        for(let i=currIndex; i<=100; i++) {
            let vo = mapCfg[i.toString()];
            if(vo.type == 3) {
                return this.scrollView.content.getChildByName(i.toString());
            }
        }
        return null;
    },

    /**
     * 移动地图标记
     * @param toIdx
     * @private
     */
    async _moveMapFlag(toIdx) {
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let vo = mapCfg[toIdx.toString()];
        let item = this.scrollView.content.getChildByName(toIdx.toString());
        // 移动
        await new Promise((res)=> {
            let pos = item.getChildByName("pos");
            cc.tween(this.map_flag)
                .to(1, {x:item.x+pos.x, y:item.y+pos.y})
                .call(()=>{
                    res();
                })
                .start();
        });

        // 播放动画
        await new Promise((res)=> {
            let animationName = "";
            if(vo.type == 3) {
                animationName = "animation" + (vo.slot.cnt-1);
            }else {
                animationName = "animation" + vo.type;
            }
            let icon = null;
            if(vo.type != 3) {
                icon = item.getChildByName("icon");
                icon.active = false;
                SlotsFacade.soundMgr.playEffect("pass3");
            }else {
               SlotsFacade.soundMgr.playEffect("pass2");
            }

            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.setAnimation(0, animationName, false)
            spine.setCompleteListener(()=>{
                spine.setCompleteListener(null);
                if(icon) {
                    icon.active = true;
                }
                res();
            });
        });
    },

    _freshMap(currIndex) {
        for(let i=1; i<=currIndex; i++) {
            this._markItemCmp(i);
        }
        if(currIndex > 0) {
            let item = this.scrollView.content.getChildByName(currIndex.toString());
            let pos = item.getChildByName("pos");
            this.map_flag.x = item.x + pos.x;
            this.map_flag.y = item.y + pos.y;
            let houseItem = this._findNextHouse(currIndex);
            let index = SlotsFacade.dm.energyData.extraFreeCnt || 0;
            houseItem.getChildByName("label_free_count").getComponent("ImgSwitchCmp").setIndex(index);
        }
    },

    /**
     * 标记完成
     */
    _markItemCmp(index) {
        let mapCfg = SlotsFacade.dm.getGameCfg().mapCfg;
        let vo = mapCfg[index.toString()];
        let item = this.scrollView.content.getChildByName(index.toString());
        let color = new cc.Color().fromHEX("#898989");
        item.getChildByName("icon").color = color;
        item.getChildByName("label_step").color = color;
        if(vo.type != 3) {
            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
            spine.node.color = color;
            spine.node.active = true;
            if(vo.type == 1) {
                spine.setAnimation(0, "animation1_2", true);
            }else {
                spine.setAnimation(0, "animation2_2", true);
            }
        } else {
            item.getChildByName("label_free_count").active = false;
        }
    },

    /**
     * map显示
     * @returns {Promise<unknown>}
     * @private
     */
    _scrollViewShow() {
        return new Promise((res)=> {
            let svNode = this.scrollView.node;
            svNode.active = true;
            cc.tween(svNode)
                .to(0.5, {y:0}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    /**
     * 显示关闭按钮
     * @returns {Promise<unknown>}
     * @private
     */
    _showCloseBtn() {
        return new Promise((res)=> {
            this.btn_close.node.active = true;
            this.btn_close.node.scale = 0;
            this.btn_close.interactable = true;
            cc.tween(this.btn_close.node)
                .to(0.3, {scale:1}, {easing:"backOut"})
                .call(()=>{
                    res();
                })
                .start();
        });
    },

    /**
     * 重置
     */
    _reset() {
        this.bg.active = false;
        this.scrollView.node.active = false;
        this.scrollView.node.y = this.scrollView.node.height/2;
        this.btn_close.node.active = false;
        this.map_game_node.active = false;
    },

    /**
     * 阻塞执行 配合 await使用
     * @param time
     * @returns {Promise<unknown>}
     * @private
     */
    _delayTime(time) {
        return new Promise((res, rej) => {
            this.scheduleOnce(()=>{res()}, time);
        });
    },
});
