/**
 * @class Magician_WheelGame
 */
cc.Class({
    extends: cc.Component,

    properties: {
        machine: null,     // 状态机
        roundCount: 20,    // 圈数

        canSpin:false,     // 是否可转

        wheel_game_node: null,

        bg:null,
        wheel:null,
        transition_ani:sp.Skeleton,

        btn_start_wheel:null,
        btn_start_spine:null,

        light_ani:null,
        fire_ani:null,
        flash_ani:null,

        board:null,

        callBack:null,

        resultData:null,
    },

    _getRotation(index) {
        let ret = -this.roundCount * 360;
        let unitAngle = 360/21;
        let indexsAngle = [
            0,
            -360+unitAngle*5,
            -360+unitAngle*6,
            -360+unitAngle*7,
            -360+unitAngle*8,
            -360+unitAngle*9,
            -360+unitAngle*10+unitAngle/2,
            -360+unitAngle*12,
            -360+unitAngle*13,
            -360+unitAngle*14,
            -360+unitAngle*15,
            -360+unitAngle*16,
        ];
        ret += indexsAngle[index];
        return ret;
    },

    onLoad() {
        this._bindView();
        this._initListener();
    },

    onDestroy() {
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this._onSubGameData, false, this);
    },

    _bindView() {
        this.wheel_game_node = this.node;
        this.bg = this.wheel_game_node.getChildByName("bg");
        this.transition_ani = SlotsFacade.mainPanel.wheel_transition_ani.getComponent(sp.Skeleton);;
        this.wheel = this.wheel_game_node.getChildByName("wheel");

        this.btn_start_wheel = this.wheel.getChildByName("btn_start_wheel");
        this.btn_start_spine = this.btn_start_wheel.getChildByName("btn_start_spine");

        this.light_ani = this.wheel.getChildByName("light_ani");
        this.fire_ani = this.wheel.getChildByName("fire_ani");
        this.flash_ani = this.wheel.getChildByName("flash_ani");

        this.board = this.wheel.getChildByName("board");
    },

    _initListener() {
        this.btn_start_wheel.on("click", this._onStartWheelHandler.bind(this), this);
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this._onSubGameData, this);
    },

    _onSubGameData(msg) {
        // {"data":{"idx":3,"rtype":2,"freeCnt":10},"uid":104682,"c":51,"code":200};
        if(msg && msg.data && msg.data.rtype == 2) {
            this.resultData = msg;
            if(msg.data.freeCnt > 0) {
                SlotsFacade.dm.addFreeCnt(msg.data.freeCnt);
            }
            this._startWheel(msg.data);
        }
    },

    async _onStartWheelHandler() {
        if(!this.canSpin) {
            return;
        }
        this.btn_start_wheel.stopAllActions();
        SlotsFacade.soundMgr.playEffect("spin");
        SlotsFacade.dm.reqSubGame(2);
    },

    async _startWheel(data) {
        this.btn_start_spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
        this.canSpin = false;

        this.transition_ani.setAnimation(0, "animation4", false);

        this.flash_ani.active = true;
        let flashAniSpin = this.flash_ani.getComponent(sp.Skeleton);
        flashAniSpin.setAnimation(0, "animation", true);
       SlotsFacade.soundMgr.playEffect("wheel_act");
        cc.tween(this.board)
            .to(8, {angle:this._getRotation(data.idx-1)}, { easing: 'quartInOut' })
            .call(()=> {
                this._completeWheel(data);
            })
            .start();

        await SlotsFacade.delayTime(2);

        this.fire_ani.active = true;
        let fireAniSpin = this.fire_ani.getComponent(sp.Skeleton);
        fireAniSpin.setAnimation(0, "animation", false);

        let max_box_mask = this.board.getChildByName("max_box_mask");
        max_box_mask.opacity = 0xff;
        cc.tween(max_box_mask)
            .delay(0.5)
            .to(0.5, {opacity:0})
            .start();
    },

    /**
     * 完成旋转
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _completeWheel(data) {
        this.flash_ani.active = false;
        if(data.idx == 1) {
            this.wheel.getChildByName("win3").active = true;
        }else if(data.idx == 7) {
            this.wheel.getChildByName("win1").active = true;
        }else {
            this.wheel.getChildByName("win2").active = true;
        }
        await SlotsFacade.delayTime(2);
        if(data.winCoin) {
            SlotsFacade.soundMgr.playEffect("wheel_popup");
            await SlotsFacade.popup.showWinGold(data.winCoin, 3)
        }
        this.exitWheelGame(data);
    },

    _reset() {
        this.resultData = {};
        this.btn_start_spine.getComponent(sp.Skeleton).setAnimation(0, "animation1", true);
        this.board.angle = 0;
        let max_box_mask = this.board.getChildByName("max_box_mask");
        max_box_mask.active = true;
        max_box_mask.opacity = 0xff;
        this.wheel.getChildByName("win1").active = false;
        this.wheel.getChildByName("win2").active = false;
        this.wheel.getChildByName("win3").active = false;
        this.fire_ani.active = false;
        this.flash_ani.active = false;
    },

    /**
     * 绑定转盘数据
     * @param {*}} data 
     */
    _bindData(data) {
        for(let i=0; i<12; i++) {
            let index = i+1;
            let vo = data[i.toString()];
            if(index == 1) {
                let freeNode = this.board.getChildByName("item1_fg");
                freeNode.active = vo.type == 1;
                let coinNode = this.board.getChildByName("item1_coin");
                coinNode.active = vo.type != 1;
                if(vo.type == 1) {
                    freeNode.getChildByName("label").getComponent(cc.Label).string = vo.el;
                }else {
                    coinNode.getChildByName("label").getComponent(cc.Label).string = Global.convertNumToShort(vo.el);
                }
            }else if(index == 7) {
                let label = this.board.getChildByName("label_7").getComponent(cc.Label);
                label.string = Global.convertNumToShort(vo.el);
            }else {
                let label = this.board.getChildByName("label_" + index).getComponent(cc.Label);
                label.string = vo.el;
            }
        }
    },

    /**
     * 退出转盘游戏
     */
    exitWheelGame() {
        let data = this.resultData.data;
        // 转场幕布动画
        SlotsFacade.mainPanel.showSceneTransition();
        // 隐藏场景
        cc.tween(this.wheel_game_node)
            .delay(2)
            .call(()=> {
                this.wheel.active = false;
                this.bg.active = false;
                this.transition_ani.node.active = false;
                if(this.callBack) {
                    this.callBack(data);
                }
                // SlotsFacade.prizePool.y += 100;
            })
            .start();
    },

    /**
     * 开始 开始转盘流程
     */
    enterWheelGame(data, cb) {
        this.callBack = cb;
        this._reset();
        this._bindData(data);
        this.transition_ani.node.active = true;
        let ske = this.transition_ani;
        Global.SlotsSoundMgr.stopBgm();
        SlotsFacade.soundMgr.playEffect("fg_trigger_popup");
        new Promise((res)=>{
            ske.setAnimation(0, "animation1", false);
            ske.setCompleteListener(()=> {
                ske.setCompleteListener(null);
                res()      
            });
        }).then((data)=> {
            // SlotsFacade.prizePool.y -= 100;
            this.bg.active = true;
            this.wheel.active = true;
            return new Promise((res)=> {
                SlotsFacade.soundMgr.playWheelBgm();
                ske.setAnimation(0, "animation2", false);
                ske.setCompleteListener(()=> {
                    ske.setCompleteListener(null);
                    res()
                });
            });
        }).then((data)=>{
            this.canSpin = true;
            cc.vv.gameData.checkAutoPlay(this.btn_start_wheel,  this._onStartWheelHandler.bind(this));
        });
    },
});
