    playPreAppear() {
        this.spineCharacterAppear.node.active = true;
        this.spineCharacterAppear.setAnimation(0, "animation", false)
        this.spineCharacterAppear.setCompleteListener(()=>{
            this.spineCharacterAppear.setCompleteListener(null);
            this.spineCharacterAppear.node.active = false;
        });
    },

    /**
     * 通过wild数量播放相应的角色动画
     * @param {number} wildCount 
     */
    play(wildCount) {
        let aniName = "skill"
        let role = "pos1"
        let len = wildCount
        let aniTime = 0
        let random = Global.random(1,100)
        if(random > 50) {
            role = "pos2"
            aniName = "skill_1"
            aniTime = 1.5
        } else {
            aniTime = 1
        }
        cc.log(aniName)
        this._spineMale.node.active = true;
        this._spineMale.setAnimation(0, aniName, false);
        let time = new Date().getTime()
        this._spineMale.setCompleteListener(()=> {
            this._spineMale.setCompleteListener(null);
            this._spineMale.setAnimation(0, "idle", true);
            cc.log(new Date().getTime() - time)
        })
        return { roleName:role, triggerTime:aniTime };
    }
