cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        wildAniCount:1, // 0不需要播放动画，1正常播放wild动画，2播放占用2个的wild动画，3播放占用3个的wild动画
    },

    StartMove() {
        this._super();
        this.wildAniCount = 1;
    },

    playWinAnimation(){
        if(this.GetShowId() == 1 && this.wildAniCount != 1) {
            this.playWildAni();
        }else {
            this._super();
        }
    },

    playWildAni() {
        if(this.wildAniCount < 1) {
            return;
        }
        let aniNode = this.setAnimationToTop(true)
        aniNode.active = true
        let spine = cc.find("w1",aniNode).getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation1_" + this.wildAniCount, false);
        spine.addAnimation(0, "animation" + this.wildAniCount, true);
    }
});