/**
 * @class Magician_Sound
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _soundPath : "games/Magician/",
        _isPlayBgm:false,
    },

    /**
     * 播放音效
     * @param audioName
     */
    playEffect(audioName, isLoop) {
        return cc.vv.AudioManager.playEff(this._soundPath, audioName, true, isLoop);
    },

    /**
     * 停止音效
     * @param audioName
     */
    stopEffectByName(audioName) {
        cc.vv.AudioManager.stopEffectByName(audioName);
    },

    stopEffect() {
        cc.vv.AudioManager.stopAudio();
    },

    playBgm:function(filename){
        if(filename) {
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm(filename);
        }else {
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    /**
     * 免费游戏背景音乐
     */
    playFreeBgm() {
        this.playBgm("fgbgm")
    },

    /**
     * scatter游戏转盘
     */
    playWheelBgm() {
        this.playBgm("mapBG_Wheelbgm")
    },
});
