/**
 * 收集进度
 * @class Magician_MapCollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        percent:0,
        _isCollectState:false,

        btn_enter: cc.Node,
        progressBar: cc.Node,
        spine_rabbit: sp.Skeleton,
        spine_tips: sp.Skeleton,
        spine_collect_end:sp.Skeleton,
        collect_track_particle:cc.Node,
        rule_tips:cc.Node,
        isOpen:false,
        canTouch:true
    },

    onLoad() {
        this._initListener();
        this.updateEnterBtn();
    },

    start() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.showCollect(true);
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);
        this.btn_enter.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(this.isOpen) {
                this._showCollectTips();
            }else {
                this._openCollect();
            }
        }, this);
    },

    /**
     * 显示提示
     */
    _showCollectTips() {
        let tips = this.rule_tips;
        if(tips.active) {
            return;
        }
        tips.active = true;
        tips.opacity = 0;
        cc.tween(tips)
            .to(1, {opacity:0xff})
            .delay(3)
            .to(1, {opacity:0})
            .call(()=>{
                tips.active = false;
            })
            .start();
    },

    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.map.enterMap(true, ()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this.isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.energyData.needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        cc.vv.gameData._serverRawMult = needBet;
        cc.vv.UserManager.setEnterSelectBet(null);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        let parentNode = cc.find("safe_node", SlotsFacade.node)
        let tempPos = this.spine_rabbit.node.convertToWorldSpaceAR(cc.v2(0,0))
        let endPos = parentNode.convertToNodeSpaceAR(tempPos)
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = parentNode.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.collect_track_particle);
            lz.parent = parentNode
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();

            promiseArr.push(new Promise((res)=>{
                cc.tween(lz)
                    .to(0.5, {x:endPos.x, y:endPos.y})
                    .call(()=> {
                        lz.removeFromParent();
                        res();
                    })
                    .start();
            }));
            SlotsFacade.soundMgr.playEffect("collect");
        });
        await Promise.all(promiseArr);
        this.setProgress(percent, true);
        this.spine_rabbit.setAnimation(0, "animation2", false);
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(!this.isOpen) {
                if(isInit) {
                    this.spine_tips.node.active = false;
                }else {
                    this.spine_tips.node.active = true;
                    this.spine_tips.setAnimation(0, "animation2", false);
                    SlotsFacade.soundMgr.playEffect("unlock");
                }
            }
        }else {
            this.spine_tips.node.active = true;
            if(isInit) {
                this.spine_tips.setAnimation(0, "animation1", false);
            }else {
                if(this.isOpen) {
                    this.spine_tips.setAnimation(0, "animation1", false);
                    SlotsFacade.soundMgr.playEffect("lock");
                }
            }
        }
        this.isOpen = boo;
    },

    /**
     * 播放收集完成动画
     */
    async playCollectEnd() {
        SlotsFacade.soundMgr.playEffect("full");
        // 播放进度条完成
        let barEffect = this.progressBar.getChildByName("bar").getChildByName("spine").getComponent(sp.Skeleton);
        barEffect.node.active = true;
        barEffect.setAnimation(0, "animation2", false);
        barEffect.setCompleteListener(()=>{
            barEffect.setCompleteListener(null);
            barEffect.node.active = false;
        });

        let vo = SlotsFacade.dm.getGameCfg().mapCfg[SlotsFacade.dm.energyData.map_idx];
        if(vo) {
            // 播放进入按钮特效
            await new Promise(res=>{
                this.spine_collect_end.node.active = true;
                this.spine_collect_end.setAnimation(0, "animation" + vo.type, false);
                this.spine_collect_end.setCompleteListener(()=>{
                    this.spine_collect_end.setCompleteListener(null);
                    this.spine_collect_end.node.active = false;
                    res();
                });
            });
        }     
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        let w = this.progressBar.width;
        let bar = this.progressBar.getChildByName("bar");
        let toX = -w + percent * w;
        if(needTransform) {
            cc.tween(bar)
            .to(0.5, {x:toX})
            .call(()=>{
                let effect = bar.getChildByName("spine").getComponent(sp.Skeleton);
                effect.node.active = true;
                effect.setAnimation(0, "animation1", false);
                effect.setCompleteListener(()=>{
                    effect.setCompleteListener(null);
                    effect.node.active = false;
                });
            })
            .start();
        }else {
            bar.x = toX;
        }
    },

    /**
     * 显示隐藏
     * @param boo
     */
    show(boo) {
        this.node.active = boo;
    },

    /**
     * 更新按钮图片
     */
    updateEnterBtn() {
        let energyData = SlotsFacade.dm.energyData;
        let nextId = energyData.map_idx + 1;
        let vo = SlotsFacade.dm.getGameCfg().mapCfg[nextId];
        if(vo) {
            let imgCmp = this.btn_enter.getComponent("ImgSwitchCmp");
            if(vo.type == 3) {
                imgCmp.setIndex(vo.slot.cnt);
            }else {
                imgCmp.setIndex(vo.type-1);
            }
        }
    }
});
