/**
 * 游戏流程控制
 * @class Magician_FlowCtrl
 */
cc.Class({ 
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            // SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = false;
            let nTotal = cc.vv.gameData.GetTotalFreeWin();
            SlotsFacade.bottomCmp.SetWin(nTotal);
            await this.enterFreeGame(true);
        }
        let deskInfo = SlotsFacade.dm.getDeskInfo();
        if(deskInfo.select && deskInfo.select.state) {
            if(deskInfo.select.rtype == 1) {
                await this.enterCollectMap(true);
            }else if(deskInfo.select.rtype == 2) {
                await this.enterScatterGame(true);
                // todo 进入免费处理

                if(SlotsFacade.dm.isFistTriggerFree()) {
                    if(SlotsFacade.dm.energyData.openGame == 2) {
                        await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.GetFreeTime());
                        SlotsFacade.mainPanel.showSceneTransition();
                        await SlotsFacade.delayTime(3.0);
                    }
                    await this.enterFreeGame();
                }
            }
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    async onMsgSpine(msg) {
        if(SlotsFacade.slots._slotsCnt == 1) {
            if(SlotsFacade.dm.hasExtraWild()) {
                await SlotsFacade.extraWildCmp.startExtraWildFlow();
            }
            SlotsFacade.slots._gameInfo = msg;
            SlotsFacade.slots.SetSlotsResult(msg);
            SlotsFacade.slots.SetReelStateInfo(msg.resultCards);
        }else {
            SlotsFacade.slots._gameInfo = msg;
            SlotsFacade.slots.SetSlotsResult(msg);
        }
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        // 能量收集
        this.collectEnergy();
        // 显示中奖路线
        SlotsFacade.extraWildCmp.hideWild();
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
        // 进入地图关卡
        await this.enterCollectMap();
        // 进入免费游戏转盘
        await this.enterScatterGame();
        // await SlotsFacade.delayTime(0.3);
        if(SlotsFacade.dm.isFistTriggerFree()) {
            if(SlotsFacade.dm.energyData.openGame == 2) {
                await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.GetFreeTime());
                SlotsFacade.mainPanel.showSceneTransition();
                await SlotsFacade.delayTime(2.0);
            }
            await this.enterFreeGame();
        }else if(SlotsFacade.dm.isLastEndFree()) {
            Global.SlotsSoundMgr.stopBgm();
            SlotsFacade.soundMgr.playEffect("fg_collect_popup");
            await SlotsFacade.popup.showWinGold(SlotsFacade.dm.getFreeWinCoin());
            SlotsFacade.mainPanel.showSceneTransition();
            await SlotsFacade.delayTime(2.0);
            this.enterNormalGame();
            await SlotsFacade.delayTime(1.0);

            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal,nTotal,true, res);
            });
        }
        SlotsFacade.slots.CanDoNextRound();
    },



    /**
     * 收集能量
     */
    async collectEnergy() {
        if(!SlotsFacade.dm.canCollect()) {
            return;
        }
        let energyData = SlotsFacade.dm.energyData;
        if(energyData && energyData.currRoundValue) {
            let items = SlotsFacade.slots.getSymbolsByServerIds(SlotsFacade.dm.getResultWildsIndex());
            let posArr = [];
            items.forEach(v => {
                posArr.push(v.node.convertToWorldSpaceAR(cc.v2(0, 0)));
            });
            await SlotsFacade.mapCollectProgress.collectEnergy(posArr, SlotsFacade.dm.getCollectPercent());
        }
    },

    /**
     * 进入收集游戏
     * @returns {Promise<void>}
     */
    async enterCollectMap(isReconnect) {
        let energyData = SlotsFacade.dm.energyData;
        if (energyData.openGame == 1 || (energyData.openGame == 2 && SlotsFacade.dm.isFistTriggerFree())) {
            SlotsFacade.topCmp.SetBackLobby(false);
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            if(!isReconnect) {
                await SlotsFacade.mapCollectProgress.playCollectEnd();
            }
            this.scheduleOnce(()=>{
                SlotsFacade.mapCollectProgress.setProgress(0);
                SlotsFacade.mapCollectProgress.updateEnterBtn();
            }, 0.5);
            return new Promise(res=>{
                SlotsFacade.map.enterMap(false, (data)=>{res(data)});
            });
        }
    },

    /**
     * 进入scatter游戏
     * @returns {Promise<void>}
     */
    async enterScatterGame(isEnterRoom) {
        let freeTurnTable = SlotsFacade.dm.freeTurnTable;
        if(freeTurnTable) {
            SlotsFacade.topCmp.SetBackLobby(false);
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            if(!isEnterRoom) {
                await SlotsFacade.slots.playScatter(SlotsFacade.dm.getScatterIndexs());
            }
            return await new Promise(res=>{
                SlotsFacade.wheelGameCmp.enterWheelGame(freeTurnTable, (data)=>{
                    if(!data || !data.freeCnt) {
                        
                    }
                    res(data)
                });
            });
        }
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame(isReconnect) {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.mapCollectProgress.show(false);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.slots.changeSlots();
        if(SlotsFacade.dm.energyData.openGame == 2) {
            SlotsFacade.mainPanel.showBg(2);
        }else {
            SlotsFacade.mainPanel.showBg(1);
            SlotsFacade.character.toFree(!isReconnect);
            if(!isReconnect) {
                await SlotsFacade.delayTime(2);
            }
        }
    },

    /**
     * 进入普通游戏
     */
    enterNormalGame() {
        Global.SlotsSoundMgr.stopBgm();

        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.character.toNormal(false);
        SlotsFacade.mapCollectProgress.show(true);
        SlotsFacade.soundMgr.playBgm();
        SlotsFacade.slots.clearFreeSymbols();
        SlotsFacade.slots.changeSlots();
    },
})